182 |     /// @inheritdoc IProposalExecutionEngine
183 |     function cancelProposal(uint256 proposalId)
184 |         external
185 |         onlyDelegateCall
186 |     {
187 |         // Must be a valid proposal ID.
188 |         if (proposalId == 0) {
189 |             revert ZeroProposalIdError();
190 |         }
191 |         Storage storage stor = _getStorage();
192 |         {
193 |             // Must be the current InProgress proposal.
194 |             uint256 currentInProgressProposalId = stor.currentInProgressProposalId;
195 |             if (currentInProgressProposalId != proposalId) {
196 |                 revert ProposalNotInProgressError(proposalId);
197 |             }
198 |         }
199 |         // Clear the current InProgress proposal ID and next progress data.
200 |         stor.currentInProgressProposalId = 0;
201 |         stor.nextProgressDataHash = 0;
202 |     }
