204 |     // Switch statement used to execute the right proposal.
205 |     function _execute(ProposalType pt, ExecuteProposalParams memory params)
206 |         internal
207 |         virtual
208 |         returns (bytes memory nextProgressData)
209 |     {
210 |         if (pt == ProposalType.ListOnOpensea) {
211 |             nextProgressData = _executeListOnOpensea(params);
212 |         } else if (pt == ProposalType.ListOnZora) {
213 |             nextProgressData = _executeListOnZora(params);
214 |         } else if (pt == ProposalType.Fractionalize) {
215 |             nextProgressData = _executeFractionalize(params);
216 |         } else if (pt == ProposalType.ArbitraryCalls) {
217 |             nextProgressData = _executeArbitraryCalls(params);
218 |         } else if (pt == ProposalType.UpgradeProposalEngineImpl) {
219 |             _executeUpgradeProposalsImplementation(params.proposalData);
220 |         } else {
221 |             revert UnsupportedProposalTypeError(uint32(pt));
222 |         }
223 |     }
